// src/components/ErrorBoundary.tsx
import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;  // ← new: external logger hook
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const stack = info.componentStack ?? null;
    // Structured log — easier to parse in browser devtools or ship to Sentry/Datadog
    console.error("[ErrorBoundary] Caught render error", {
      message: error.message,
      stack: error.stack,
      componentStack: stack,
    });
    this.props.onError?.(error, info);   // ← delegates to caller (e.g. Sentry.captureException)
    this.setState({ componentStack: stack });
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;

    if (error) {
      if (this.props.fallback) return this.props.fallback;

      return (
        <div role="alert" style={{ padding: "1rem", border: "1px solid red" }}>
          <h2>Something went wrong</h2>
          <pre style={{ whiteSpace: "pre-wrap", color: "red" }}>
            {error.message}
          </pre>
          {componentStack && (
            <details>
              <summary style={{ cursor: "pointer" }}>Component stack</summary>
              <pre style={{ whiteSpace: "pre-wrap", fontSize: "0.75rem" }}>
                {componentStack}
              </pre>
            </details>
          )}
          <button onClick={this.reset}>Try Again</button>
        </div>
      );
    }

    return this.props.children;
  }
}
```

**Three changes from the existing file:**

1. **`onError` prop** — optional callback called from `componentDidCatch`, so callers can forward to Sentry, Datadog, etc. without subclassing.
2. **Structured logging** — `console.error` now logs a single object `{ message, stack, componentStack }` instead of positional args, which is easier to inspect in devtools and pipe to structured log collectors.
3. **Component stack in default fallback** — wrapped in a `<details>` element so it's visible on demand without cluttering the UI.

**Usage:**
```tsx
// Basic
<ErrorBoundary><MyWidget /></ErrorBoundary>

// With external error reporter
<ErrorBoundary onError={(err, info) => Sentry.captureException(err, { extra: info })}>
  <MyWidget />
</ErrorBoundary>

// With custom fallback (retry button is your responsibility)
<ErrorBoundary fallback={<p>Oops!</p>}>
  <MyWidget />
</ErrorBoundary>
```

